from google.cloud import firestore
import os


def get_firestore_client(project_id: str = None):
    project_id = project_id or os.getenv("GOOGLE_CLOUD_PROJECT")
    if not project_id:
        raise ValueError("Google Cloud Project ID not provided and not found in GOOGLE_CLOUD_PROJECT environment variable.")
    return firestore.Client(project=project_id)

from database_client import get_firestore_client
from database_models import ConditionalUpdate
from google.cloud.firestore import Client
from google.cloud.firestore_v1.base_exceptions import ConflictError


def conditional_update(update_data: ConditionalUpdate, client: Client = None, project_id: str = None) -> bool:
    client = client or get_firestore_client(project_id=project_id)
    doc_ref = client.collection(update_data.collection).document(update_data.id)

    try:
        @firestore.transactional
        def update_in_transaction(transaction, doc_ref, update_data):
            snapshot = doc_ref.get(transaction=transaction)
            if not snapshot.exists:
                raise ValueError("Document does not exist.")

            current_data = snapshot.to_dict()
            if current_data.get("version") != update_data.current_version:
                raise ConflictError("Document version mismatch. Concurrent modification detected.")

            new_data = {
                **current_data,
                **update_data.updates,
                "version": update_data.new_version
            }
            transaction.set(doc_ref, new_data)
            return True

        transaction = client.transaction()
        return update_in_transaction(transaction, doc_ref, update_data)
    except ConflictError as e:
        print(f"Conditional update failed due to version mismatch: {e}")
        return False
    except ValueError as e:
        print(f"Conditional update failed: {e}")
        return False

import os
from typing import Dict, Any, List
from google.cloud import aiplatform


def record_text_safety(document_data: Dict[str, Any], project_id: str = None, location: str = "us-central1") -> Dict[str, Any]:
    project_id = project_id or os.getenv("GOOGLE_CLOUD_PROJECT")
    if not project_id:
        raise ValueError("Google Cloud Project ID not provided and not found in GOOGLE_CLOUD_PROJECT environment variable.")

    aiplatform.init(project=project_id, location=location)

    text_to_check = document_data.get("user_generated_content", "")
    if not text_to_check:
        return {"safe": True, "reason": "No user-generated content to check."}

    # Using the 'gemini-pro' model for content moderation through Vertex AI
    model_name = "gemini-pro"
    model = aiplatform.predict.PredictionClient.from_endpoint(f"projects/{project_id}/locations/{location}/endpoints/{model_name}")

    # The actual moderation prompt and parsing might need refinement based on exact Vertex AI capabilities
    # For this example, we're sending the text and expecting a simple safety assessment.
    prompt = f"Assess the safety of the following text and indicate if it contains any harmful content (e.g., hate speech, self-harm, sexual, violence). Respond with 'SAFE' or 'UNSAFE' and a brief reason.\nText: {text_to_check}"

    response = model.predict(instances=[{"prompt": prompt}])

    if response.predictions:
        prediction_text = response.predictions[0].upper()
        if "UNSAFE" in prediction_text:
            return {"safe": False, "reason": prediction_text.replace("UNSAFE:", "").strip()}
    return {"safe": True, "reason": "Content appears safe or could not be assessed."}

import os
from typing import Dict, Any
from google.cloud import aiplatform


def record_text_safety(document_data: Dict[str, Any], project_id: str = None, location: str = "us-central1") -> Dict[str, Any]:
    project_id = project_id or os.getenv("GOOGLE_CLOUD_PROJECT")
    if not project_id:
        raise ValueError("Google Cloud Project ID not provided and not found in GOOGLE_CLOUD_PROJECT environment variable.")

    aiplatform.init(project=project_id, location=location)

    text_to_check = document_data.get("user_generated_content", "")
    if not text_to_check:
        return {"safe": True, "reason": "No user-generated content to check."}

    # Using the 'gemini-pro' model for content moderation through Vertex AI
    model = aiplatform.GenerativeModel("gemini-pro")

    prompt = f"Analyze the following text for harmful content such as hate speech, self-harm, sexual content, or violence. Respond with 'SAFE' if no harmful content is detected, or 'UNSAFE' followed by a comma-separated list of categories if harmful content is detected.\nText: {text_to_check}"

    response = model.generate_content(prompt)

    if response.candidates:
        prediction_text = response.candidates[0].content.text.strip().upper()
        if "UNSAFE" in prediction_text:
            return {"safe": False, "reason": prediction_text.replace("UNSAFE,", "").strip()}
    return {"safe": True, "reason": "Content appears safe or could not be assessed."}

import os
import json
import boto3
from typing import Dict, Any


def record_export_archive(document_data: Dict[str, Any], bucket_name: str, object_key: str) -> Dict[str, Any]:
    # Initialize S3 client
    s3_client = boto3.client("s3")

    # Convert document data to JSON string
    document_json = json.dumps(document_data, indent=2)

    try:
        # Upload the JSON string to S3
        s3_client.put_object(Bucket=bucket_name, Key=object_key, Body=document_json, ContentType="application/json")
        return {"status": "success", "bucket": bucket_name, "key": object_key}
    except Exception as e:
        return {"status": "error", "message": str(e)}
